const Camera=require('./camera-settings');
const defaults={bindings:{up:['KeyW','ArrowUp'],right:['KeyD','ArrowRight'],down:['KeyS','ArrowDown'],left:['KeyA','ArrowLeft'],attack:['Space'],pickup:['KeyE'],talk:['KeyT'],inventory:['KeyI'],quests:['KeyQ'],market:['KeyB'],settings:['Escape'],zoomIn:['Equal','NumpadAdd'],zoomOut:['Minus','NumpadSubtract']},viewMode:'classic',cameraTilt:Camera.policy.defaultTilt,cameraZoom:Camera.policy.defaultZoom,cutaway:true,sceneQuality:1,turnDelay:110,controller:true,touch:'auto',touchSize:58,touchOpacity:.8,touchLeft:4,touchRight:4,touchBottom:10,tracker:null,arrows:null};
function load(){try{return {...defaults,...JSON.parse(localStorage.getItem('odyssey-settings')||'{}'),bindings:{...defaults.bindings,...JSON.parse(localStorage.getItem('odyssey-settings')||'{}').bindings}};}catch{return JSON.parse(JSON.stringify(defaults));}}
class Controls{
 constructor(action){this.settings=load();this.settings.cameraTilt=Camera.tilt(this.settings.cameraTilt);this.settings.cameraZoom=Camera.zoom(this.settings.cameraZoom);this.held=new Set();this.action=action;this.padPrevious=new Set();this.rebinding=null;this.changed=()=>{};}
 save(){localStorage.setItem('odyssey-settings',JSON.stringify(this.settings));this.changed();}
 reset(){this.settings=JSON.parse(JSON.stringify(defaults));this.held.clear();this.save();}
 down(e){if(this.rebinding){e.preventDefault();const action=this.rebinding;if(Object.entries(this.settings.bindings).some(([k,v])=>k!==action&&v.includes(e.code))){this.changed('That key is already assigned.');return;}this.settings.bindings[action]=[e.code];this.rebinding=null;this.save();return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)||e.ctrlKey||e.altKey||e.metaKey)return;const entry=Object.entries(this.settings.bindings).find(([,keys])=>keys.includes(e.code));if(!entry)return;e.preventDefault();const action=entry[0];if(['up','right','down','left'].includes(action))this.held.add(action);else if(!e.repeat)this.action(action);}
 up(e){for(const[a,keys]of Object.entries(this.settings.bindings))if(keys.includes(e.code))this.held.delete(a);}
 clear(){this.held.clear();this.padPrevious.clear();}
 direction(){let actions=new Set(this.held);if(this.settings.controller){try{const p=Array.from(navigator.getGamepads?.()||[]).find(Boolean);if(p){if(p.axes[0]<-.35||p.buttons[14]?.pressed)actions.add('left');if(p.axes[0]>.35||p.buttons[15]?.pressed)actions.add('right');if(p.axes[1]<-.35||p.buttons[12]?.pressed)actions.add('up');if(p.axes[1]>.35||p.buttons[13]?.pressed)actions.add('down');const map={0:'attack',1:'talk',2:'pickup',3:'inventory',4:'quests',5:'market',9:'settings'},pressed=new Set();for(const[id,action]of Object.entries(map))if(p.buttons[id]?.pressed){pressed.add(action);if(!this.padPrevious.has(action))this.action(action);}this.padPrevious=pressed;}else this.padPrevious.clear();}catch{}}return actions.has('up')?0:actions.has('right')?1:actions.has('down')?2:actions.has('left')?3:-1;}
 touchVisible(){return this.settings.touch==='on'||this.settings.touch==='auto'&&('ontouchstart'in window||navigator.maxTouchPoints>0);}
}
module.exports={Controls,defaults};
